# 00b extraction: platelet count, INR, aPTT, creatinine, bilirubin and haemoglobin (all times), anticoagulant and antiplatelet orders with dose,
# blood-product transfusions, vasopressors, renal replacement therapy, procedures and diagnosis positions from raw csv.gz files
suppressMessages({library(DBI);library(data.table)})
MM<-paste0(Sys.getenv("MIMIC_DIR"),"/"); EE<-paste0(Sys.getenv("EICU_DIR"),"/")
con<-dbConnect(duckdb::duckdb(shared_home=FALSE),":memory:"); invisible(dbExecute(con,"PRAGMA threads=8")); Q<-function(s) as.data.table(dbGetQuery(con,s))
r<-function(p) sprintf("read_csv('%s',all_varchar=true,ignore_errors=true)",p)
saveRDS(Q(sprintf("select hadm_id::bigint hadm_id,itemid::int itemid,charttime::timestamp charttime,try_cast(valuenum as double) v from %s where itemid in ('51265','51237','51275','50912','50885','51222') and hadm_id is not null",r(paste0(MM,"hosp/labevents.csv.gz")))),"h_mlab.rds")
saveRDS(Q(sprintf("select hadm_id::bigint hadm_id,starttime::timestamp starttime,drug,route,dose_val_rx dose,dose_unit_rx unit,doses_per_24_hrs n24 from %s where lower(drug) similar to '.*(heparin|enoxaparin|dalteparin|fondaparinux|argatroban|bivalirudin|apixaban|rivaroxaban|warfarin|dabigatran|edoxaban|aspirin|clopidogrel|ticagrelor|prasugrel|cangrelor).*'",r(paste0(MM,"hosp/prescriptions.csv.gz")))),"h_mrx.rds")
saveRDS(Q(sprintf("select stay_id::bigint stay_id,itemid::int itemid,starttime::timestamp starttime,try_cast(amount as double) amount,statusdescription from %s where itemid in ('225170','225168','220970','221906','222315','221749','221662','221289')",r(paste0(MM,"icu/inputevents.csv.gz")))),"h_minp.rds")
saveRDS(Q(sprintf("select stay_id::bigint stay_id,itemid::int itemid,starttime::timestamp starttime from %s where itemid in ('225802','225803','225805','225809','225955','225441')",r(paste0(MM,"icu/procedureevents.csv.gz")))),"h_mrrt.rds")
saveRDS(Q(sprintf("select hadm_id::bigint hadm_id,icd_code,icd_version from %s",r(paste0(MM,"hosp/procedures_icd.csv.gz")))),"h_mproc.rds")
saveRDS(Q(sprintf("select hadm_id::bigint hadm_id,try_cast(seq_num as int) seq,icd_code from %s",r(paste0(MM,"hosp/diagnoses_icd.csv.gz")))),"h_mdx.rds")
saveRDS(Q(sprintf("select patientunitstayid::bigint s,try_cast(labresultoffset as int) o,labname n,try_cast(labresult as double) v from %s where labname in ('PT - INR','PTT','platelets x 1000','creatinine','total bilirubin','Hgb')",r(paste0(EE,"lab.csv.gz")))),"h_elab.rds")
saveRDS(Q(sprintf("select patientunitstayid::bigint s,try_cast(drugstartoffset as int) o,drugname,routeadmin,dosage from %s where lower(drugname) similar to '.*(heparin|enoxaparin|lovenox|dalteparin|fragmin|fondaparinux|argatroban|bivalirudin|warfarin|coumadin|apixaban|eliquis|rivaroxaban|xarelto|dabigatran|aspirin|clopidogrel|plavix|ticagrelor|brilinta|prasugrel|effient).*'",r(paste0(EE,"medication.csv.gz")))),"h_emed.rds")
saveRDS(Q(sprintf("select patientunitstayid::bigint s,try_cast(treatmentoffset as int) o,treatmentstring d from %s where lower(treatmentstring) like '%%transfusion%%' or lower(treatmentstring) like '%%blood product%%' or lower(treatmentstring) like '%%ecmo%%' or lower(treatmentstring) like '%%dialysis%%' or lower(treatmentstring) like '%%crrt%%'",r(paste0(EE,"treatment.csv.gz")))),"h_etr.rds")
saveRDS(Q(sprintf("select patientunitstayid::bigint s,try_cast(intakeoutputoffset as int) o,celllabel d,try_cast(cellvaluenumeric as double) v from %s where lower(celllabel) similar to '.*(platelet|prbc|packed red|red blood cell).*'",r(paste0(EE,"intakeOutput.csv.gz")))),"h_eio.rds")
saveRDS(Q(sprintf("select patientunitstayid::bigint s,try_cast(diagnosisoffset as int) o,lower(diagnosisstring) d from %s where lower(diagnosisstring) like '%%pneumonia%%'",r(paste0(EE,"diagnosis.csv.gz")))),"h_epna.rds")
saveRDS(Q(sprintf("select patientunitstayid::bigint s,try_cast(infusionoffset as int) o,lower(drugname) d from %s where lower(drugname) similar to '.*(norepi|levophed|vasopressin|phenyleph|neo-syn|dopamine|epineph).*'",r(paste0(EE,"infusionDrug.csv.gz")))),"h_einf.rds")
cat("done\n")
